/**
 * Typed API client generated from the backend OpenAPI document (docs/04 §11.3, NFR-MNT-03).
 * `schema.d.ts` is regenerated by `make api-client`; CI fails when it is out of date.
 */
import createClient, { type Middleware } from "openapi-fetch";

import type { paths } from "./schema";

export interface ApiFieldError {
  field: string;
  code: string;
  message: string;
}

/** A problem+json error (docs/06 §3). */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    readonly detail: string | null,
    readonly errors: ApiFieldError[],
    readonly requestId: string | null,
    readonly body: Record<string, unknown>,
  ) {
    super(detail ?? code);
    this.name = "ApiError";
  }
}

const CSRF_COOKIE = "tcms_csrf";
const UNSAFE = new Set(["POST", "PUT", "PATCH", "DELETE"]);

export function readCookie(name: string, cookies: string = document.cookie): string | null {
  for (const part of cookies.split(";")) {
    const [k, ...v] = part.trim().split("=");
    if (k === name) return decodeURIComponent(v.join("="));
  }
  return null;
}

let onUnauthenticated: ((returnTo: string) => void) | null = null;

/** Registered by the auth feature to redirect to sign-in on 401. */
export function setUnauthenticatedHandler(fn: ((returnTo: string) => void) | null): void {
  onUnauthenticated = fn;
}

export async function toApiError(response: Response): Promise<ApiError> {
  let body: Record<string, unknown>;
  try {
    body = (await response.clone().json()) as Record<string, unknown>;
  } catch {
    body = {};
  }
  const str = (v: unknown) => (typeof v === "string" ? v : null);
  return new ApiError(
    response.status,
    str(body.code) ?? "http_error",
    str(body.detail) ?? str(body.title),
    Array.isArray(body.errors) ? (body.errors as ApiFieldError[]) : [],
    str(body.request_id) ?? response.headers.get("x-request-id"),
    body,
  );
}

export const csrfMiddleware: Middleware = {
  onRequest({ request }) {
    if (UNSAFE.has(request.method)) {
      const token = readCookie(CSRF_COOKIE);
      if (token) request.headers.set("X-CSRF-Token", token);
    }
    return request;
  },
};

export const errorMiddleware: Middleware = {
  async onResponse({ response }) {
    if (response.ok) return response;
    const error = await toApiError(response);
    if (error.status === 401 && onUnauthenticated) {
      onUnauthenticated(window.location.pathname + window.location.search);
    }
    throw error;
  },
};

export const api = createClient<paths>({ baseUrl: "/", credentials: "include" });
api.use(csrfMiddleware, errorMiddleware);
